"""Merge one JSON object into another.

Fields of `patch` are merged into `base`. Where both hold an object, the two
objects are merged the same way, recursively. Any other value in `patch`,
an array, a scalar or `null`, replaces the field in `base`: arrays are never
concatenated, and `null` is kept as a value rather than deleting the field.
Neither input is changed; the merged object is the result.
"""

import json
import sys

TOOL = "json_merge"
INPUTS = ("base", "patch")
TYPE_NAMES = (
    (dict, "an object"),
    (list, "an array"),
    (str, "a string"),
    (bool, "a boolean"),
    (int, "a number"),
    (float, "a number"),
)


def fail(status, message):
    sys.stderr.write(message)
    sys.exit(status)


def read_inputs():
    inputs = json.loads(sys.stdin.buffer.read().decode("utf-8"))

    for name in inputs:
        if name not in INPUTS:
            fail(2, f"{TOOL} does not take the input {name!r}.")

    for name in INPUTS:
        if name not in inputs:
            fail(2, f"{TOOL} needs the input {name!r}.")

    return inputs


def type_name(value):
    for kind, name in TYPE_NAMES:
        if isinstance(value, kind):
            return name

    return "null"


def merge(base, patch):
    merged = dict(base)

    for key, value in patch.items():
        if isinstance(value, dict) and isinstance(merged.get(key), dict):
            merged[key] = merge(merged[key], value)
        else:
            merged[key] = value

    return merged


inputs = read_inputs()

for name in INPUTS:
    if not isinstance(inputs[name], dict):
        fail(2, f"{TOOL} can only merge objects; {name} is {type_name(inputs[name])}.")

result = merge(inputs["base"], inputs["patch"])

sys.stdout.buffer.write(json.dumps({"value": result}, ensure_ascii=False).encode("utf-8"))
